import re
from datetime import datetime

def parse_log(line):
    m = re.fullmatch(r'(\d{4}-\d\d-\d\d \d\d:\d\d:\d\d),(\d{3}) \[(\w+)\] (.+?): (.*)', line)
    if not m:
        raise ValueError(line)
    ts = datetime.strptime(m[1], '%Y-%m-%d %H:%M:%S').replace(microsecond=int(m[2]) * 1000)
    level = m[3].upper()
    if level == 'WARNING':
        level = 'WARN'
    return {'ts': ts, 'level': level, 'logger': m[4], 'msg': m[5]}
```

