from datetime import timedelta

def add_business_days(d, n, holidays):
    def ok(x):
        return x.weekday() < 5 and x not in holidays

    if n == 0:
        while not ok(d):
            d += timedelta(days=1)
        return d
    step, left = timedelta(days=1 if n > 0 else -1), abs(n)
    while left:
        d += step
        if ok(d):
            left -= 1
    return d
